def now_ts():
    return int(time.time())


def close_terminal_process(pid, fd):
    """The terminal reader owns both the PTY descriptor and child reaping."""
    try:
        os.close(fd)
    except OSError:
        pass
    for sig in (signal.SIGHUP, signal.SIGTERM, signal.SIGKILL):
        try:
            # Reap first so an already exited child is never signalled again.
            if os.waitpid(pid, os.WNOHANG)[0]:
                return
            os.kill(pid, sig)
        except ProcessLookupError:
            pass
        except ChildProcessError:
            return
        deadline = time.monotonic() + 1
        while time.monotonic() < deadline:
            try:
                if os.waitpid(pid, os.WNOHANG)[0]:
                    return
            except ChildProcessError:
                return
            time.sleep(0.05)
    # SIGKILL has been sent; collect the child rather than leaving a zombie.
    try:
        os.waitpid(pid, 0)
    except ChildProcessError:
        pass


def expire_ssh_http_sessions():
    now = now_ts()
    with SSH_HTTP_LOCK:
        for sid, session in list(SSH_HTTP_SESSIONS.items()):
            with session["lock"]:
                expired = now - session["last_seen"] > 15 * 60
                closed = not session["alive"] and now - session.get("closed_at", now) > 60
                if expired or closed:
                    session["alive"] = False
                    SSH_HTTP_SESSIONS.pop(sid, None)


def stop_ssh_http_sessions():
    with SSH_HTTP_LOCK:
        sessions = list(SSH_HTTP_SESSIONS.values())
        SSH_HTTP_SESSIONS.clear()
        for session in sessions:
            with session["lock"]:
                session["alive"] = False
    for session in sessions:
        thread = session.get("thread")
        if thread and thread.ident is not None and thread is not threading.current_thread():
            thread.join(timeout=5)


@contextmanager
def atomic_output_path(path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = None
    try:
        with tempfile.NamedTemporaryFile(prefix=f".{path.name}.", suffix=".tmp", dir=path.parent, delete=False) as output:
            tmp = Path(output.name)
        yield tmp
        os.replace(tmp, path)
    finally:
        if tmp is not None:
            tmp.unlink(missing_ok=True)


def atomic_write_text(path, text, mode=None):
    with atomic_output_path(path) as tmp:
        tmp.write_text(text, encoding="utf-8")
        if mode is not None:
            os.chmod(tmp, mode)


def iso_time(ts):
    if not ts:
        return ""
    return dt.datetime.fromtimestamp(int(ts), tz=dt.timezone.utc).isoformat()


def format_router_note_time(ts):
    if not ts:
        return "Дата публикации неизвестна"
    return dt.datetime.fromtimestamp(int(ts), tz=dt.timezone.utc).strftime("%d.%m.%Y %H:%M UTC")


def router_proxy_limiter(router_id):
    with ROUTER_PROXY_LOCK:
        limiter = ROUTER_PROXY_LIMITERS.get(router_id)
        if limiter is None:
            limiter = threading.BoundedSemaphore(ROUTER_PROXY_LIMIT)
            ROUTER_PROXY_LIMITERS[router_id] = limiter
