def ios_hub_document_path(path):
    return path in {"/", "/login", "/logout", "/donate", "/donate/", "/vps-terminal", "/vps-terminal/",
                    "/router-updates", "/router-updates/", "/ssh-key-manual/"} or path.startswith("/ssh/") or (
        path.startswith("/router/") and path.endswith(("/notes", "/config", "/xray-control")))


def ios_install_target(value):
    value = str(value or "/")
    if len(value) > 2048 or "\\" in value or any(ord(char) < 32 for char in value):
        return "/"
    try:
        parsed = urllib.parse.urlsplit(value)
    except ValueError:
        return "/"
    if parsed.scheme or parsed.netloc or not value.startswith("/") or parsed.path == "/logout" or not ios_hub_document_path(parsed.path):
        return "/"
    return value


