def ssh_ws_token(secret, router_id):
    return hmac.new(
        secret.encode("utf-8"),
        f"ssh:{router_id}".encode("utf-8"),
        hashlib.sha256,
    ).hexdigest()


def strip_access_prefix(path, router_id):
    prefix = f"/access/{urllib.parse.quote(router_id)}"
    if path == prefix:
        return "/"
    if path.startswith(prefix + "/"):
        return path[len(prefix):] or "/"
    return path or "/"


def rewrite_forward_url(value, router_id, port):
    if not value:
        return value
    parsed = urllib.parse.urlsplit(value)
    path = strip_access_prefix(parsed.path, router_id)
    return urllib.parse.urlunsplit(("http", f"127.0.0.1:{port}", path, parsed.query, parsed.fragment))


def ws_accept_value(key):
    raw = hashlib.sha1((key + WS_GUID).encode("ascii")).digest()
    return base64.b64encode(raw).decode("ascii")


def recv_exact(sock, size):
    chunks = []
    left = size
    while left > 0:
        chunk = sock.recv(left)
        if not chunk:
            raise ConnectionError("websocket closed")
        chunks.append(chunk)
        left -= len(chunk)
    return b"".join(chunks)


def ws_read_frame(sock):
    head = recv_exact(sock, 2)
    first, second = head[0], head[1]
    opcode = first & 0x0F
    masked = bool(second & 0x80)
    length = second & 0x7F
    if length == 126:
        length = struct.unpack("!H", recv_exact(sock, 2))[0]
    elif length == 127:
        length = struct.unpack("!Q", recv_exact(sock, 8))[0]
    mask = recv_exact(sock, 4) if masked else b""
    payload = recv_exact(sock, length) if length else b""
    if masked and payload:
        payload = bytes(b ^ mask[i % 4] for i, b in enumerate(payload))
    return opcode, payload


def ws_send_frame(sock, payload, opcode=1):
    if isinstance(payload, str):
        payload = payload.encode("utf-8", errors="replace")
    length = len(payload)
    if length < 126:
        head = struct.pack("!BB", 0x80 | opcode, length)
    elif length < 65536:
        head = struct.pack("!BBH", 0x80 | opcode, 126, length)
    else:
        head = struct.pack("!BBQ", 0x80 | opcode, 127, length)
    sock.sendall(head + payload)


def set_pty_size(fd, rows, cols):
    try:
        rows = max(8, min(80, int(rows or 24)))
        cols = max(20, min(260, int(cols or 80)))
    except Exception:
        return False
    try:
        import fcntl
        import termios

        fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
        return True
    except Exception:
        return False


def write_pty_all(fd, data, timeout=10.0, chunk_size=1024):
    if isinstance(data, str):
        data = data.encode("utf-8", errors="replace")
    view = memoryview(data or b"")
    total = 0
    deadline = time.monotonic() + timeout
    while total < len(view):
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            raise TimeoutError("terminal input write timed out")
        _, writable, _ = select.select([], [fd], [], min(1.0, remaining))
        if fd not in writable:
            continue
        written = os.write(fd, view[total : total + chunk_size])
        if written <= 0:
            raise OSError("terminal input write returned 0 bytes")
        total += written
    return total


def parse_resize_payload(payload):
    try:
        message = json.loads(payload.decode("utf-8", errors="ignore"))
    except Exception:
        return None
    if not isinstance(message, dict) or message.get("type") != "resize":
        return None
    return message.get("rows"), message.get("cols")


def vps_resource_widgets_html(mobile=False, resources=None):
    kind = "mobile" if mobile else "desktop"
    widgets = []
    for key, label in (("cpu", "ЦП"), ("memory", "ОЗУ"), ("disk", "ДИСК")):
        metric = (resources or {}).get(key) or {}
        percent = metric.get("percent")
        valid = isinstance(percent, (int, float)) and not isinstance(percent, bool) and math.isfinite(percent)
        value = (f"{percent:.1f}".rstrip("0").rstrip(".").replace(".", ",") + "%") if valid else "—"
        title = html.escape(label + ": " + (value if valid else "данные пока недоступны"), quote=True)
        usage = max(0, min(100, percent)) if valid else 0
        widgets.append(
            f'<div class="vpsResource badge" data-vps-resource="{key}" style="--hub-usage:{usage:.1f}%" title="{title}" aria-label="{title}">'
            f'<span>{label}</span><strong data-vps-resource-value>{value}</strong></div>'
        )
    return f'<div class="vpsResources vpsResources-{kind}" role="group" aria-label="Ресурсы VPS">{"".join(widgets)}</div>'



